def ng(frame,r0,r1,c0,c1):
    a=frame.ascii.split('\n')
    cells=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if a[r][c]=='B']
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    rr0,cc0=min(rs),min(cs)
    return frozenset((r-rr0,c-cc0) for r,c in cells)

